var param = {
	"id":"ggb",
	"height":600,
	"width":1140,
	"showToolBar":false,
	"borderColor":null,
	"showMenuBar":false,
	"showAlgebraInput":false,
	"showResetIcon":false,
	"enableLabelDrags":true,
	"enableShiftDragZoom":true,
	"enableRightClick":false,
	"capturingThreshold":null,
	"showToolBarHelp":false,
	"errorDialogsActive":false,
	"useBrowserForJS":true,
	"showFullscreenButton":true,
	"ggbBase64":""};

var ggbApplet = new GGBApplet(param, '5.0');
ggbApplet.setHTML5Codebase("/vendor/geogebra/GeoGebra/HTML5/5.0/web3d/");
window.onload = function() {
	ggbApplet.inject('geogebra','preferHTML5');	
}

ggb = document.ggb;

function gerarPlano() {


	var func = document.getElementById('funcao');
	var k = document.getElementById('constante');
	var p = document.getElementById('ponto');


	if(func.value.match(/sqrt/)){
    	var ret = func.value.replace(/sqrt/g,'');
    	var ksqrt = ggb.evalCommand("ksq = "+k.value+"^2");
    	var ks = ggb.getValue("ksq");
		var fun_eq = verificar_funcao(ret,ks);
		ggb.evalCommand("Supe: "+fun_eq);
		ggb.setColor("Supe",202,31,123);

	}
	else{
		var fun_eq1 = verificar_funcao(func.value,k.value);
		ggb.evalCommand("Supe: "+fun_eq1);
		ggb.setColor("Supe",202,31,123);
	}
	var sup = ggb.evalCommandCAS("Supe");
	ggb.evalCommand("fun(x,y,z) ="+func.value);
	ggb.evalCommand("P = ("+p.value+")");
	ggb.evalCommand("pertence = IsInRegion(P,Supe)");
	var pert = ggb.getValueString("pertence");
	ggb.evalCommand("If(pertence==false, Delete(P))");
	avisar(pert);

	ggb.evalCommand("f'x(x,y,z) = Derivative(fun,x)");
	ggb.evalCommand("f'y(x,y,z) = Derivative(fun,y)");
	ggb.evalCommand("f'z(x,y,z) = Derivative(fun,z)");

	ggb.evalCommand("q = f'x(P)");
	ggb.evalCommand("w = f'y(P)");
	ggb.evalCommand("ha = f'z(P)");

	ggb.evalCommand("grad = (q,w,ha)");
	ggb.evalCommand("gradu = UnitVector(grad)");
	ggb.evalCommand("Pf = Point(P,gradu)");

	ggb.evalCommand("VetorGrad = Vector(P,Pf)");


	ggb.evalCommand("xp = x(P)");
	ggb.evalCommand("yp = y(P)");
	ggb.evalCommand("zp = z(P)");

	var q = ggb.getValue("q");
	var x = ggb.getValue("xp");
	var w = ggb.getValue("w");
	var y = ggb.getValue("yp");
	var e = ggb.getValue("ha");
	var z = ggb.getValue("zp");




	if(func.value.match(/sin/)||func.value.match(/cos/)||func.value.match(/ln/)||func.value.match(/e/))
	{
		ggb.evalCommand("devzp = -1");
		var derivaz = ggb.getValue("devzp");
		ggb.evalCommand("grad = (q,w,devzp)");
		ggb.evalCommand("gradu = UnitVector(grad)");
		ggb.evalCommand("Pf = Point(P,gradu)");

		ggb.evalCommand("VetorGrad = Vector(P,Pf)");
  		
		ggb.evalCommand("ptg: q*(x-(x(P))) + w*(y-(y(P))) - (z-(z(P)))=0");
		var pltg = ggb.getValueString("ptg");

		qx.innerHTML = q;
		wy.innerHTML = w;
		ez.innerHTML = derivaz;
		superf.innerHTML = sup+" = - z";
		plantg.innerHTML = pltg;


	}
	else 
	{
		ggb.evalCommand("ptg: q*(x-(x(P))) + w*(y-(y(P))) + ha*(z-(z(P)))=0");
  		var pltg = ggb.getValueString("ptg");

  		qx.innerHTML = q;
		wy.innerHTML = w;
		ez.innerHTML = e;
		superf.innerHTML = sup;
		plantg.innerHTML = pltg;

	}


	ggb.setVisible("grad",false);
	ggb.setVisible("gradu",false);
	ggb.setVisible("Pf",false);
	ggb.setVisible("devz",false);
	ggb.setVisible("devzp",false);
	ggb.setVisible("dev",false);

	ggb.setFixed ("P", true, false);
	ggb.setLabelVisible ("P", true);
	ggb.setLabelVisible ("VetorGrad", true);
	ggb.setLabelVisible ("ptg", true);
	ggb.setLabelVisible ("Supe", true);
	ggb.setColor("Supe",202,31,123);	

	xp.innerHTML = x;
	yp.innerHTML = y;
	zp.innerHTML = z;

	eixoX();

}

function gerarSolido()
{
	ggb.reset("ptg");
	var func = document.getElementById('funcao');
	var k = document.getElementById('constante');

	if(func.value.match(/sqrt/)){
    	var ret = func.value.replace(/sqrt/g,'');
    	var ksqrt = ggb.evalCommand("ksq = "+k.value+"^2");
    	var ks = ggb.getValue("ksq");
		var fun_eq = verificar_funcao(ret,ks);
		ggb.evalCommand("Supe: "+fun_eq);
		ggb.setColor("Supe",202,31,123);

	}
	else{
		var fun_eq1 = verificar_funcao(func.value,k.value);
		ggb.evalCommand("Supe: "+fun_eq1);
		ggb.setColor("Supe",202,31,123);
	}
}

function exibirAreaX() {
	var areax;
	areax = ggb.getLaTeXString("ax");
	document.getElementById("res-ax").innerHTML = areax;
	
}


function eixoX() {

	exibirAreaX();
}



function verificar_funcao(a,b)
{
	if(a.match(/sin/)||a.match(/cos/)||a.match(/ln/)||a.match(/e/))
	{
  		var eq1 = ggb.evalCommandCAS(a+"-"+b);
	}
	else
	{
		var eq1 = ggb.evalCommandCAS(a+"="+b);
	}
	return eq1;
}

function avisar(a)
{
	if(a == "pertence = false")
	{
		alert("Ponto não está na superficie");
		document.getElementById('img_de_conf').src = "plano_tg/errado.png"﻿;
	}
	else
	{
		document.getElementById('img_de_conf').src = "plano_tg/ok-xxl.png"﻿;
		document.getElementById("resultadox").style.display = "block";
	}
}
